"""Finite direct interpreter for standalone typed HIA operations.

No source AST, source compiler, LLVM, or producer receipt participates.  Defined
program traps and analysis budgets are different outcomes.  Resource counters
describe the stopped program state; traps/budget stops do not pretend that an
aborting native process performed normal-path destructor cleanup.
"""
from __future__ import annotations

from dataclasses import dataclass

from .hia_program import (HIAProgramRejected, OWNERS, RESOURCES, SCALARS, WIDTHS,
                          integer_range, scalar_value_valid, verify_program)
from .hia_bounded_memory import fill_bytes, move_bytes
from .hia_schema import supports_feature
from .hia_opcodes import ExecutionObservationRejected, validate_execution_observation


class HIAProgramTrap(ArithmeticError):
    """A specified aborting program operation, not an interpreter budget."""

    def __init__(self, code, message):
        self.code, self.report = code, None
        super().__init__(f"E_HIA_TRAP_{code.upper()}: {message}")


class HIAProgramBudgetExceeded(RuntimeError):
    """A finite evaluator resource limit; says nothing about termination."""

    def __init__(self, code, message):
        self.code, self.report = code, None
        super().__init__(f"E_HIA_BUDGET_{code.upper()}: {message}")


@dataclass(eq=False)
class _Owner:
    ident: int
    data: bytearray
    active: bool = True


@dataclass(eq=False)
class _View:
    parent: _Owner | _View
    mutable: bool
    active: bool = True


@dataclass(eq=False)
class _ChainNode:
    storage: _Owner
    payload: _Owner
    tail: _ChainNode | None


@dataclass(eq=False)
class _Chain:
    ident: int
    head: _ChainNode | None
    active: bool = True


# The native v7 object model has a 16-byte buffer descriptor and one 8-byte
# successor pointer. Node storage is charged to the same live-byte budget as
# user buffers, and consumes the same allocation-failure sequence.
CHAIN_NODE_BYTES = 24


def _underlying(value):
    seen = set()
    while isinstance(value, _View):
        if not value.active or id(value) in seen:
            raise HIAProgramRejected("expired/cyclic runtime view", "E_HIA_RUNTIME_INVARIANT")
        seen.add(id(value))
        value = value.parent
    if not isinstance(value, _Owner) or not value.active:
        raise HIAProgramRejected("expired runtime owner", "E_HIA_RUNTIME_INVARIANT")
    return value


def _wrap(value, typ):
    width = WIDTHS[typ]
    value &= (1 << width) - 1
    if typ.startswith("i") and value >= (1 << (width - 1)):
        value -= 1 << width
    return value


def _checked(value, typ):
    lo, hi = integer_range(typ)
    if not lo <= value <= hi:
        raise HIAProgramTrap("overflow", f"result is outside {typ}")
    return value


class _Machine:
    def __init__(self, program, max_steps, max_heap_bytes, allocation_fail_at, max_call_depth):
        self.program = program
        document = program.as_dict()
        self.functions = {f["name"]: f for f in document["functions"]}
        self.recursive_chain = supports_feature(document["schema"], "recursive_chain")
        self.max_steps, self.max_heap_bytes = max_steps, max_heap_bytes
        self.allocation_fail_at, self.max_call_depth = allocation_fail_at, max_call_depth
        self.steps = self.allocations = self.frees = self.allocation_attempts = 0
        self.live_bytes = self.peak_bytes = self.owner_count = self.drops = 0
        self.loans_started = self.loans_ended = 0
        self.owners = {}
        self.chains = {}
        self.chains_created = self.chains_consumed = 0
        self.chain_nodes_created = self.chain_nodes_dropped = 0

    def tick(self):
        self.steps += 1
        if self.steps > self.max_steps:
            raise HIAProgramBudgetExceeded("steps", "finite step limit reached")

    def resources(self):
        result = {"allocations": self.allocations, "frees": self.frees,
                "allocation_attempts": self.allocation_attempts,
                "owners_created": self.owner_count, "owners_dropped": self.drops,
                "live_owners": len(self.owners), "live_bytes": self.live_bytes,
                "peak_bytes": self.peak_bytes,
                "loans_started": self.loans_started, "loans_ended": self.loans_ended,
                "live_local_loans": self.loans_started - self.loans_ended}
        # Existing profiles retain the original report shape. New counters
        # describe the recursive data structure independently of byte owners.
        if self.recursive_chain:
            result.update({"chains_created": self.chains_created,
                           "chains_consumed": self.chains_consumed,
                           "live_chains": len(self.chains),
                           "chain_nodes_created": self.chain_nodes_created,
                           "chain_nodes_dropped": self.chain_nodes_dropped,
                           "live_chain_nodes": self.chain_nodes_created - self.chain_nodes_dropped})
        return result

    def new_chain(self, head=None):
        self.chains_created += 1
        chain = _Chain(self.chains_created, head)
        self.chains[chain.ident] = chain
        return chain

    def chain_head(self, chain):
        if not isinstance(chain, _Chain) or not chain.active or self.chains.get(chain.ident) is not chain:
            raise HIAProgramRejected("expired runtime chain", "E_HIA_RUNTIME_INVARIANT")
        return chain.head

    def consume_chain(self, chain):
        head = self.chain_head(chain)
        del self.chains[chain.ident]
        chain.active, chain.head = False, None
        self.chains_consumed += 1
        return head

    def drop_chain(self, chain):
        head = self.consume_chain(chain)
        # Destruction is iterative. A runtime-sized list does not consume one
        # Python/native stack frame per node. Charge work to the step budget;
        # an interrupted destruction is a budget stop, not claimed cleanup.
        while head is not None:
            self.tick()
            tail = head.tail
            self.drop(head.payload)
            self.drop(head.storage)
            self.chain_nodes_dropped += 1
            head.tail = None
            head = tail

    def new_owner(self, data):
        self.owner_count += 1
        owner = _Owner(self.owner_count, data)
        self.owners[owner.ident] = owner
        if data:
            self.allocations += 1
        self.live_bytes += len(data)
        self.peak_bytes = max(self.peak_bytes, self.live_bytes)
        return owner

    def allocate(self, size, optional):
        # Zero-size owners are real capabilities but require no allocator call,
        # cannot fail, and do not consume the deterministic failure injection.
        if size == 0:
            return self.new_owner(bytearray()), True
        if size > (1 << 63) - 1:
            if optional:
                return self.new_owner(bytearray()), False
            raise HIAProgramTrap("allocation", "allocation exceeds the 64-bit object-size model")
        # A host evaluator budget is not reported as a program malloc failure.
        if size > self.max_heap_bytes - self.live_bytes:
            raise HIAProgramBudgetExceeded("heap", "finite live-byte limit reached")
        self.allocation_attempts += 1
        failed = self.allocation_fail_at == self.allocation_attempts
        if not failed:
            try:
                return self.new_owner(bytearray(size)), True
            except (MemoryError, OverflowError):
                failed = True
        if failed and optional:
            return self.new_owner(bytearray()), False
        raise HIAProgramTrap("allocation", "allocator returned failure")

    def drop(self, owner):
        owner = _underlying(owner)
        if owner.ident not in self.owners:
            raise HIAProgramRejected("duplicate runtime drop", "E_HIA_RUNTIME_INVARIANT")
        del self.owners[owner.ident]
        self.drops += 1
        if owner.data:
            self.frees += 1
        self.live_bytes -= len(owner.data)
        owner.active = False
        owner.data = bytearray()

    def operation(self, ins, env, depth):
        op, attrs = ins["op"], ins["attrs"]
        names = ins["args"]
        args = [env[name] for name in names]
        outputs = ins["out"]
        typ = outputs[0]["type"] if outputs else None
        result = []
        if op == "const":
            result = [attrs["value"]]
        elif op in {f"int.{a}.{m}" for a in ("add", "sub", "mul") for m in ("checked", "wrap")}:
            a, b = args
            kind = op.split(".")[1]
            value = a + b if kind == "add" else a - b if kind == "sub" else a * b
            result = [(_checked if op.endswith("checked") else _wrap)(value, typ)]
        elif op in {"int.div.checked", "int.rem.checked"}:
            a, b = args
            if b == 0:
                raise HIAProgramTrap("division_by_zero", "integer divisor is zero")
            lo, _ = integer_range(typ)
            if typ.startswith("i") and a == lo and b == -1:
                raise HIAProgramTrap("overflow", "signed minimum divided by minus one")
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = [quotient if op == "int.div.checked" else a - quotient * b]
        elif op in {"int.shl.checked", "int.shr.checked"}:
            a, b = args
            if not 0 <= b < WIDTHS[typ]:
                raise HIAProgramTrap("overflow", "shift count is outside the word width")
            result = [_wrap(a << b, typ) if op == "int.shl.checked" else a >> b]
        elif op == "int.neg.checked":
            result = [_checked(-args[0], typ)]
        elif op in {"bit.and", "bit.or", "bit.xor"}:
            a, b = args
            value = a & b if op == "bit.and" else a | b if op == "bit.or" else a ^ b
            result = [_wrap(value, typ)]
        elif op == "bit.not":
            result = [_wrap(~args[0], typ)]
        elif op.startswith("compare."):
            a, b = args
            result = [{"compare.eq": a == b, "compare.ne": a != b,
                       "compare.lt": a < b, "compare.le": a <= b,
                       "compare.gt": a > b, "compare.ge": a >= b}[op]]
        elif op == "bool.not":
            result = [not args[0]]
        elif op == "bool.and":
            result = [args[0] and args[1]]
        elif op == "bool.or":
            result = [args[0] or args[1]]
        elif op == "int.cast":
            result = [(_checked if attrs["mode"] == "checked" else _wrap)(args[0], typ)]
        elif op == "select":
            result = [args[1] if args[0] else args[2]]
        elif op in {"buffer.new", "buffer.try_new"}:
            owner, ok = self.allocate(args[0], op == "buffer.try_new")
            result = [owner] + ([ok] if op == "buffer.try_new" else [])
        elif op == "buffer.len":
            result = [len(_underlying(args[0]).data)]
        elif op == "chain.empty":
            result = [self.new_chain()]
        elif op == "chain.try_push":
            chain, payload = args
            head = self.chain_head(chain)
            _underlying(payload)
            storage, ok = self.allocate(CHAIN_NODE_BYTES, True)
            if ok:
                node = _ChainNode(storage, payload, head)
                self.chain_nodes_created += 1
                fallback = self.new_owner(bytearray())
                self.consume_chain(chain)
                result = [self.new_chain(node), fallback, True]
            else:
                # The failed allocation's logical empty owner is internal.
                # Both caller-owned inputs survive in fresh output names.
                self.drop(storage)
                self.consume_chain(chain)
                result = [self.new_chain(head), payload, False]
            for name in names:
                del env[name]
        elif op == "chain.pop":
            head = self.consume_chain(args[0])
            if head is None:
                result = [self.new_chain(), self.new_owner(bytearray()), False]
            else:
                tail, payload = head.tail, head.payload
                self.drop(head.storage)
                self.chain_nodes_dropped += 1
                head.tail = None
                result = [self.new_chain(tail), payload, True]
            del env[names[0]]
        elif op == "chain.is_empty":
            result = [self.chain_head(args[0]) is None]
        elif op in {"chain.head_read", "chain.head_mut"}:
            head = self.chain_head(args[0])
            if head is None:
                raise HIAProgramTrap("bounds", "head borrow of an empty chain")
            _underlying(head.payload)
            result = [_View(head.payload, op == "chain.head_mut")]
            self.loans_started += 1
        elif op in {"borrow.read", "borrow.mut"}:
            _underlying(args[0])
            result = [_View(args[0], op == "borrow.mut")]
            self.loans_started += 1
        elif op == "loan.end":
            view = args[0]
            _underlying(view)
            if not isinstance(view, _View):
                raise HIAProgramRejected("end of non-view", "E_HIA_RUNTIME_INVARIANT")
            view.active = False
            self.loans_ended += 1
            del env[names[0]]
        elif op == "owner.move":
            if isinstance(args[0], _Chain):
                self.chain_head(args[0])
            else:
                _underlying(args[0])
            result = [env.pop(names[0])]
        elif op == "owner.drop":
            if isinstance(args[0], _Chain):
                self.drop_chain(args[0])
            else:
                self.drop(args[0])
            del env[names[0]]
        elif op == "buffer.load":
            owner, index = _underlying(args[0]), args[1]
            if index >= len(owner.data):
                raise HIAProgramTrap("bounds", "byte load outside the borrowed buffer")
            result = [owner.data[index]]
        elif op == "buffer.store":
            owner, index, value = _underlying(args[0]), args[1], args[2]
            if not isinstance(args[0], _View) or not args[0].mutable:
                raise HIAProgramRejected("write through non-mutable view", "E_HIA_RUNTIME_INVARIANT")
            if index >= len(owner.data):
                raise HIAProgramTrap("bounds", "byte store outside the borrowed buffer")
            owner.data[index] = value
        elif op == "buffer.fill":
            owner, value = _underlying(args[0]), args[1]
            if not isinstance(args[0], _View) or not args[0].mutable:
                raise HIAProgramRejected("fill without a mutable view", "E_HIA_RUNTIME_INVARIANT")
            # Bounded host scratch, not an O(owner_length) temporary.
            # The HIA Owner allocation and its declared effects are unchanged.
            try:
                fill_bytes(owner.data, 0, len(owner.data), value)
            except MemoryError as exc:
                raise HIAProgramBudgetExceeded("host_memory", "bulk fill exceeds host memory") from exc
        elif op == "buffer.copy":
            destination, source, size = _underlying(args[0]), _underlying(args[1]), args[2]
            if not isinstance(args[0], _View) or not args[0].mutable or not isinstance(args[1], _View):
                raise HIAProgramRejected("copy requires checked mutable and shared loans", "E_HIA_RUNTIME_INVARIANT")
            if destination is source:
                raise HIAProgramRejected("copy alias escaped static owner verification", "E_HIA_RUNTIME_INVARIANT")
            if size > len(destination.data) or size > len(source.data):
                raise HIAProgramTrap("bounds", "bulk copy exceeds an owner extent")
            # Distinct live allocations are guaranteed by the verified roots.
            memoryview(destination.data)[:size] = memoryview(source.data)[:size]
        elif op == "buffer.move_within":
            # Exact memmove semantics, including overlapping byte ranges.
            # All offsets are already verified usize; prove each subrange
            # fits before any write (subtraction cannot underflow here).
            owner = _underlying(args[0])
            destination, source, size = args[1:]
            if not isinstance(args[0], _View) or not args[0].mutable:
                raise HIAProgramRejected("in-place move needs a unique mutable loan",
                                         "E_HIA_RUNTIME_INVARIANT")
            extent = len(owner.data)
            if (destination > extent or source > extent
                    or size > extent - destination or size > extent - source):
                raise HIAProgramTrap("bounds", "in-place byte range exceeds owned extent")
            if size:
                # Match memmove overlap semantics without O(size) host scratch.
                try:
                    move_bytes(owner.data, destination, source, size)
                except MemoryError as exc:
                    raise HIAProgramBudgetExceeded(
                        "host_memory", "in-place copy exceeds host memory") from exc
        elif op == "buffer.fill_range":
            view, offset, size, value = args
            owner = _underlying(view)
            if not isinstance(view, _View) or not view.mutable:
                raise HIAProgramRejected("range fill requires unique mutable loan",
                                         "E_HIA_RUNTIME_INVARIANT")
            extent = len(owner.data)
            if offset > extent or size > extent - offset:
                raise HIAProgramTrap("bounds", "fill range exceeds owned extent")
            if size:
                try:
                    fill_bytes(owner.data, offset, size, value)
                except MemoryError as exc:
                    raise HIAProgramBudgetExceeded(
                        "host_memory", "range fill exceeds host memory") from exc
        elif op == "buffer.copy_range":
            dest_view, src_view = args[:2]
            destination, source = _underlying(dest_view), _underlying(src_view)
            dst_offset, src_offset, size = args[2:]
            if (not isinstance(dest_view, _View) or not dest_view.mutable
                    or not isinstance(src_view, _View) or destination is source):
                raise HIAProgramRejected("range copy violates checked distinct-owner loans",
                                         "E_HIA_RUNTIME_INVARIANT")
            dst_size, src_size = len(destination.data), len(source.data)
            if (dst_offset > dst_size or src_offset > src_size
                    or size > dst_size - dst_offset or size > src_size - src_offset):
                raise HIAProgramTrap("bounds", "cross-owner range copy exceeds byte extent")
            if size:
                memoryview(destination.data)[dst_offset:dst_offset + size] = (
                    memoryview(source.data)[src_offset:src_offset + size])
        elif op == "buffer.swap":
            owner = _underlying(args[0])
            left, right = args[1:]
            if not isinstance(args[0], _View) or not args[0].mutable:
                raise HIAProgramRejected("swap needs one live mutable borrow",
                                         "E_HIA_RUNTIME_INVARIANT")
            # Snapshot both source bytes before modifying either position.
            if left >= len(owner.data) or right >= len(owner.data):
                raise HIAProgramTrap("bounds", "swap byte offset outside owner extent")
            a, b = owner.data[left], owner.data[right]
            owner.data[left], owner.data[right] = b, a
        elif op == "call":
            callee = self.functions[attrs["function"]]
            for name, param in zip(names, callee["params"]):
                if param["type"] in OWNERS:
                    del env[name]
            result = self.invoke(callee, args, depth + 1)
        else:
            raise HIAProgramRejected("unhandled verified opcode", "E_HIA_RUNTIME_INVARIANT")
        if len(result) != len(outputs):
            raise HIAProgramRejected("runtime result arity mismatch", "E_HIA_RUNTIME_INVARIANT")
        for output, value in zip(outputs, result):
            if output["type"] in SCALARS and not scalar_value_valid(value, output["type"]):
                raise HIAProgramRejected("runtime produced an invalid scalar", "E_HIA_RUNTIME_INVARIANT")
            env[output["name"]] = value

    def invoke(self, fn, arguments, depth=0):
        # Root invocation occupies frame 1 (depth=0), matching the static
        # max_call_depth budget. A limit of N admits exactly N live frames.
        # Refuse the (N+1)th BEFORE its call-entry tick or any side effect.
        if depth >= self.max_call_depth:
            raise HIAProgramBudgetExceeded("calls", "finite call-depth limit reached")
        self.tick()
        blocks = {b["id"]: b for b in fn["blocks"]}
        current = fn["entry"]
        env = {p["name"]: a for p, a in zip(fn["params"], arguments)}
        while True:
            block = blocks[current]
            for ins in block["ops"]:
                self.tick()
                self.operation(ins, env, depth)
            self.tick()
            term = block["term"]
            if term["op"] == "ret":
                values = [env[name] for name in term["values"]]
                bindings = {p["name"]: a for p, a in zip(fn["params"], arguments)}
                for index, (typ, origin) in enumerate(zip(fn["returns"], fn.get("return_loans", [None] * len(values)))):
                    if typ not in {"readbuf", "mutbuf"}:
                        continue
                    value, parent = values[index], bindings[origin]
                    _underlying(value)
                    _underlying(parent)
                    if (not isinstance(value, _View) or not isinstance(parent, _View)
                            or typ == "mutbuf" and (not value.mutable or not parent.mutable)):
                        raise HIAProgramRejected("returned view permission invariant", "E_HIA_RUNTIME_INVARIANT")
                    if value is parent:
                        # Forwarding must not expose one consumable runtime view
                        # as both the caller's parent and its returned child.
                        values[index] = _View(parent, typ == "mutbuf")
                        self.loans_started += 1
                    elif value.parent is not parent:
                        raise HIAProgramRejected("returned view origin invariant", "E_HIA_RUNTIME_INVARIANT")
                return values
            if term["op"] == "trap":
                raise HIAProgramTrap(term["code"], "explicit core trap")
            edge = term if term["op"] == "jump" else term["then"] if env[term["cond"]] else term["else"]
            target = blocks[edge["target"]]
            values = [env[name] for name in edge["args"]]
            # All block inputs are evaluated simultaneously. Loop iterations
            # create new dynamic instances of the same static SSA names.
            env = {p["name"]: a for p, a in zip(target["params"], values)}
            current = target["id"]

    def report(self, function, status, values=None, error=None, *, external_roots=()):
        # Borrowed entry storage belongs to its caller, not this VM's heap.
        # Accept actual live roots from the reference adapter, not a producer's
        # reported count. This preserves the aggregate loan-backing invariant;
        # it is not a new proof of the complete dynamic view graph.
        if (type(external_roots) is not tuple
                or any(type(root) is not _Owner or type(root.ident) is not int
                       or root.ident >= 0 or root.active is not True
                       or type(root.data) is not bytearray for root in external_roots)
                or len({id(root) for root in external_roots}) != len(external_roots)
                or len({root.ident for root in external_roots}) != len(external_roots)
                or len({id(root.data) for root in external_roots}) != len(external_roots)
                or any(root.ident in self.owners
                       or any(root is owner for owner in self.owners.values())
                       for root in external_roots)):
            raise HIAProgramRejected("invalid external runtime roots", "E_HIA_RUNTIME_INVARIANT")
        resources = self.resources()
        try:
            validate_execution_observation(status, resources, steps=self.steps,
                max_steps=self.max_steps, max_heap_bytes=self.max_heap_bytes,
                error_code=error.code if error is not None else None,
                with_chains=self.recursive_chain, allow_host_memory=True,
                live_external_roots=len(external_roots))
        except ExecutionObservationRejected as exc:
            raise HIAProgramRejected(str(exc), "E_HIA_RUNTIME_INVARIANT") from exc
        result = {"schema": "hepta.hia.program-execution.v1", "status": status,
                  "program_sha256": self.program.sha256, "function": function,
                  "input_sha256": self.program.input_sha256,
                  "steps": self.steps, "resources": resources,
                  "word_bits": 64, "source_used": False,
                  "claims": {"finite_core_execution": True,
                             "whole_language_soundness_proved": False,
                             "backend_refinement_proved": False}}
        if values is not None:
            result["values"] = values
            result["result"] = values[0] if len(values) == 1 else values
        if error is not None:
            result["error"] = {"code": error.code, "message": str(error)}
        return result


def execute_program(program, function, arguments, *, max_steps=1_000_000,
                    max_heap_bytes=16 * 1024 * 1024, allocation_fail_at=None,
                    max_call_depth=256, bounded_resource_limits=None,
                    profile=None, linux_stdio_provider=None,
                    linux_process_startup=None, linux_process_provider=None, linux_cli_components=None, linux_file_provider=None,
                    linux_file_render_components=None, linux_file_roundtrip_components=None):
    """Verify immutable bytes, then execute a scalar public entry point.

    Owners and views can be created, moved and called internally. Python callers
    cannot fabricate them: public interpreter inputs/outputs are scalar values.
    Resource-returning functions remain available as internal core functions.
    """
    if linux_file_roundtrip_components is not None and not (
            type(profile) is str and profile == "hepta.hia.linux-file-roundtrip.v2"):
        raise HIAProgramRejected("roundtrip components require their exact profile",
                                 "E_HIA_LINUX_FILE_ROUNDTRIP_PROFILE")
    if profile is not None:
        if type(profile) is str and profile == "hepta.hia.linux-file-roundtrip.v2":
            from .hia_linux_file_roundtrip import execute_linux_file_roundtrip
            if (bounded_resource_limits is not None or linux_stdio_provider is not None
                    or linux_process_provider is not None or linux_cli_components is not None
                    or linux_file_render_components is not None):
                raise HIAProgramRejected("separate file-render authority required", "E_HIA_LINUX_FILE_RENDER_PROFILE")
            return execute_linux_file_roundtrip(program, function, arguments,
                provider=linux_file_provider, startup=linux_process_startup,
                components=linux_file_roundtrip_components,
                max_steps=max_steps, max_heap_bytes=max_heap_bytes,
                allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
        elif type(profile) is str and profile == "hepta.hia.linux-file-render.v3":
            from .hia_linux_file_render import execute_linux_file_render
            if (bounded_resource_limits is not None or linux_stdio_provider is not None
                    or linux_process_provider is not None or linux_cli_components is not None):
                raise HIAProgramRejected("separate file-render authority required", "E_HIA_LINUX_FILE_RENDER_PROFILE")
            return execute_linux_file_render(program, function, arguments,
                provider=linux_file_provider, startup=linux_process_startup,
                components=linux_file_render_components,
                max_steps=max_steps, max_heap_bytes=max_heap_bytes,
                allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
        if linux_file_render_components is not None:
            raise HIAProgramRejected("file-render components require their exact profile", "E_HIA_LINUX_FILE_RENDER_PROFILE")
        if type(profile) is str and profile == "hepta.hia.linux-file.v1":
            from .hia_linux_file import execute_linux_file
            if (bounded_resource_limits is not None or linux_stdio_provider is not None
                    or linux_process_provider is not None or linux_cli_components is not None):
                raise HIAProgramRejected("separate file-profile authority required", "E_HIA_LINUX_FILE_PROFILE")
            return execute_linux_file(program, function, arguments,
                provider=linux_file_provider, startup=linux_process_startup,
                max_steps=max_steps, max_heap_bytes=max_heap_bytes,
                allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
        if linux_file_provider is not None:
            raise HIAProgramRejected("file provider requires exact file profile", "E_HIA_LINUX_FILE_PROFILE")
        if type(profile) is str and profile == "hepta.hia.linux-cli-process.v1":
            from .hia_linux_cli_process import execute_linux_cli_process
            if bounded_resource_limits is not None or linux_stdio_provider is not None:
                raise HIAProgramRejected("separate CLI-process authority required", "E_HIA_LINUX_CLI_PROCESS_PROFILE")
            return execute_linux_cli_process(program, function, arguments,
                provider=linux_process_provider, startup=linux_process_startup, components=linux_cli_components,
                max_steps=max_steps, max_heap_bytes=max_heap_bytes,
                allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
        if linux_cli_components is not None:
            raise HIAProgramRejected("CLI components require exact CLI profile", "E_HIA_LINUX_CLI_PROCESS_PROFILE")
        if type(profile) is str and profile == "hepta.hia.linux-process.v1":
            from .hia_linux_process import execute_linux_process
            if bounded_resource_limits is not None or linux_stdio_provider is not None:
                raise HIAProgramRejected("separate process-profile authority and provider required",
                                         "E_HIA_LINUX_PROCESS_PROFILE")
            return execute_linux_process(program, function, arguments,
                provider=linux_process_provider, startup=linux_process_startup,
                max_steps=max_steps, max_heap_bytes=max_heap_bytes,
                allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
        if linux_process_startup is not None or linux_process_provider is not None:
            raise HIAProgramRejected("startup authority requires the exact process profile",
                                     "E_HIA_LINUX_PROCESS_PROFILE")
        from .hia_linux_stdio import require_profile, execute_linux_stdio
        require_profile(profile)
        if bounded_resource_limits is not None:
            raise HIAProgramRejected("ordinary Core budget receipts do not admit Linux I/O",
                                     "E_HIA_LINUX_STDIO_PROFILE")
        return execute_linux_stdio(program, function, arguments, provider=linux_stdio_provider,
            max_steps=max_steps, max_heap_bytes=max_heap_bytes,
            allocation_fail_at=allocation_fail_at, max_call_depth=max_call_depth)
    if linux_stdio_provider is not None or linux_process_startup is not None or linux_process_provider is not None or linux_cli_components is not None or linux_file_provider is not None or linux_file_render_components is not None:
        raise HIAProgramRejected("physical-effect provider requires an explicit profile",
                                 "E_HIA_LINUX_STDIO_PROFILE")
    checked = verify_program(program)
    if (type(function) is not str or type(arguments) not in (list, tuple)
            or type(max_steps) is not int or not 1 <= max_steps <= 10_000_000
            or type(max_heap_bytes) is not int or not 0 <= max_heap_bytes <= 1024 * 1024 * 1024
            or type(max_call_depth) is not int or not 1 <= max_call_depth <= 256
            or allocation_fail_at is not None and
               (type(allocation_fail_at) is not int or allocation_fail_at < 1)):
        raise HIAProgramRejected("invalid entry arguments/evaluator limits", "E_HIA_INPUT")
    # Validate and execute one immutable invocation. The caller may mutate an
    # exact list while scalar validation runs; rereading it after validation
    # could substitute an untyped value, change arity or alter an allocation
    # extent. Admitted scalar values themselves are immutable built-ins.
    arguments = tuple(arguments)
    if function not in checked.scalar_entrypoints:
        raise HIAProgramRejected("nominal/internal signatures are not public scalar entries", "E_HIA_INPUT")
    budget = None
    if bounded_resource_limits is not None:
        from .hia_static_budget import HIAStaticBudgetRejected, qualify_bounded_resources
        budget = qualify_bounded_resources(checked, limits=bounded_resource_limits)
        row = next(row for row in budget["exports"] if row["function"] == function)
        # Smaller evaluator limits remain meaningful, but cannot silently
        # invalidate the finite profile promised for this invocation.
        if (max_steps < row["max_vm_ticks"] or max_heap_bytes < row["max_live_heap_bytes"]
                or max_call_depth < row["max_call_depth"]):
            raise HIAStaticBudgetRejected("E_HIA_BUDGET_POLICY",
                "evaluator limits are below the selected entry's qualified resource bounds")
        max_steps = min(max_steps, budget["limits"]["max_vm_ticks"])
        max_heap_bytes = min(max_heap_bytes, budget["limits"]["max_live_heap_bytes"])
        max_call_depth = min(max_call_depth, budget["limits"]["max_call_depth"])
    from .hia_program_execution_native import selected_program_execution
    native = selected_program_execution()
    if native is not None:
        try:
            observed = native.execute(checked, function, arguments, max_steps=max_steps,
                max_heap_bytes=max_heap_bytes, allocation_fail_at=allocation_fail_at,
                max_call_depth=max_call_depth)
        except (HIAProgramTrap, HIAProgramBudgetExceeded) as exc:
            if budget is not None:
                exc.report['bounded_resources'] = budget
            raise
        if budget is not None:
            observed['bounded_resources'] = budget
        return observed
    machine = _Machine(checked, max_steps, max_heap_bytes, allocation_fail_at, max_call_depth)

    def report(status, values=None, error=None):
        observed = machine.report(function, status, values, error)
        if budget is not None:
            observed["bounded_resources"] = budget
        return observed
    fn = machine.functions.get(function)
    if fn is None or len(fn["params"]) != len(arguments):
        raise HIAProgramRejected("unknown entry/wrong argument count", "E_HIA_INPUT")
    if any(p["type"] in RESOURCES for p in fn["params"]) or any(t in RESOURCES for t in fn["returns"]):
        raise HIAProgramRejected("public evaluator boundary cannot carry capabilities", "E_HIA_INPUT")
    if any(not scalar_value_valid(a, p["type"]) for p, a in zip(fn["params"], arguments)):
        raise HIAProgramRejected("entry arguments are not exactly typed machine values", "E_HIA_INPUT")
    try:
        values = machine.invoke(fn, arguments)
    except HIAProgramTrap as exc:
        exc.report = report("trapped", error=exc)
        raise
    except HIAProgramBudgetExceeded as exc:
        exc.report = report("budget_exceeded", error=exc)
        raise
    except RecursionError as exc:
        limit = HIAProgramBudgetExceeded("calls", "host recursion limit reached")
        limit.report = report("budget_exceeded", error=limit)
        raise limit from exc
    if machine.owners or machine.chains or machine.loans_started != machine.loans_ended:
        raise HIAProgramRejected("successful scalar entry leaked a verified resource", "E_HIA_RUNTIME_INVARIANT")
    return report("returned", values)

"""Independent action traces, byte-format oracle, and private-frame faults."""
from hashlib import sha256
import struct
from observations import require,dump,pin

ABI=0xfffffffd
U64=(1<<64)-1
UUID=bytes(range(1,17));NONCE=bytes(range(33,49));TXN=bytes(range(65,81))
ROOT=sha256(b'expected-catalog-root').digest();TARGET=sha256(b'proposed-ten-table-root').digest();REQUEST=sha256(b'request-record').digest()
GROUPS=('head-genesis-commit','head-partial-eintr','head-replay-conflict','head-lost-ack',
    'head-eintr-refusals','head-effect-errors','head-protocol-errors','head-sha-format',
    'head-generation-boundaries','head-abi-extents','head-dirty-seal','head-terminal-observe')

def replace(raw,at,value):
    b=bytearray(raw);b[at:at+len(value)]=value;return bytes(b)
def word(raw,at,value):return replace(raw,at,struct.pack('<Q',value))
def rehash(raw):return raw[:224]+sha256(raw[:224]).digest()
def seal(raw):
    value=1469598103934665603
    for i,b in enumerate(raw):
        if not 248<=i<256:value=(((value<<7)|(value>>57))^b)&U64
    return word(raw,248,value)
def head(O,generation=0,root=ROOT,uuid=UUID,txn=None):
    return O.encode_head(store_uuid=uuid,generation=generation,parent_generation=max(0,generation-1),root=root,
        parent_root=bytes(32) if generation==0 else sha256(b'parent-root').digest(),
        transaction_uuid=bytes(16) if generation==0 else (bytes(range(17,33)) if txn is None else txn),
        request_digest=bytes(32) if generation==0 else sha256(b'prior-request').digest())

class Frame:
    def __init__(self,engine,O,name,expected=None,current=None):
        self.O=O;self.session=engine.session(name);self.expected=head(O) if expected is None else expected
        self.target=O.target_head(self.expected,TARGET,TXN,REQUEST)
        self.current=self.expected if current is None else current
        self.serial=1;self.action=1;self.phase=1;self.status=1;self.claimed=0
        self.possible=0;self.sync=0;self.replay=0;self.desired=0;self.reason=0
        self.read_position=0;self.write_position=0
        source=O.initial_request(nonce=NONCE,expected=self.expected,root=TARGET,transaction_uuid=TXN,request_digest=REQUEST)
        value,output,workspace=self.session.call(source,'initialize')
        self.expect(value,output)
        require(workspace[256:512]==self.expected and workspace[512:768]==self.target,
            'actual independently checksummed expected/target head bytes differ')
    def expect(self,value,output):
        receipt=self.O.decode_receipt(output,value)
        expected=dict(status=self.status,action=self.action,serial=self.serial,phase=self.phase,claimed=self.claimed,
            possible_publication=self.possible,directory_sync_ack=self.sync,exact_target_replay=self.replay,
            nonce_low=int.from_bytes(NONCE[:8],'little'),nonce_high=int.from_bytes(NONCE[8:],'little'),
            desired_outcome=self.desired,reason=self.reason)
        if self.action in (2,6,9):expected.update(payload=b'',offset=self.read_position,extent=256-self.read_position)
        elif self.action==4:expected.update(payload=self.target[self.write_position:],offset=self.write_position,extent=256-self.write_position)
        elif self.action in (3,7):expected.update(payload=b'.hiah-'+NONCE.hex().encode()+b'\0',offset=0,extent=0)
        else:expected.update(payload=b'',offset=0,extent=0)
        expected['payload_length']=len(expected['payload'])
        require(receipt==expected,'independent full head receipt differs: '+self.session.name+' / '+str(self.session.n))
        dump(self.session.directory/('ORACLE-%04d.json'%self.session.n),
            {k:(v.hex() if type(v)is bytes else v) for k,v in expected.items()})
    def source(self,event,*,serial=None,action=None,result=0,payload=b'',nonce=NONCE):
        return self.O.request(event=event,serial=self.serial if serial is None else serial,
            action=self.action if action is None else action,result=result,nonce=nonce,payload=payload)
    def call(self,raw,label):
        value,output,workspace=self.session.call(raw,label);self.expect(value,output);return workspace
    def claim(self):
        raw=self.source(1);self.serial+=1;self.claimed=1
        if self.action==7:self.possible=1
        return self.call(raw,'claim-'+str(self.action))
    def acknowledge(self,result=0,payload=b'',next_action=None,reason=None):
        action=self.action;raw=self.source(2,result=result,payload=payload)
        if reason is not None:
            self.status=3;self.phase=15;self.action=0;self.reason=reason
        else:
            require(next_action is not None,'expected next action must be explicit')
            self.serial+=1;self.claimed=0
            if result==U64-3:
                require(next_action==action,'EINTR does not advance an effect')
            else:
                if action in (2,6,9):self.read_position=(self.read_position+result)%256
                if action==4:self.write_position+=result
                if action==8:self.sync=1
                if action==2 and next_action==8:self.possible=1;self.replay=1
                if action==2 and next_action==11:self.desired=2
            self.action=next_action
            self.phase=next_action if next_action else (14 if self.desired==2 else 13)
            self.status=1 if next_action else (2 if self.desired==2 else 0)
        return self.call(raw,'ack-'+str(action))
    def advance_one(self):
        action=self.action;self.claim()
        if action==1:self.acknowledge(next_action=2)
        elif action==2:
            nxt=8 if self.current==self.target else 3 if self.current==self.expected else 11
            self.acknowledge(256-self.read_position,self.current[self.read_position:],nxt)
        elif action==3:self.acknowledge(19,next_action=4)
        elif action==4:self.acknowledge(256-self.write_position,next_action=5)
        elif action==5:self.acknowledge(next_action=6)
        elif action==6:self.acknowledge(256-self.read_position,self.target[self.read_position:],7)
        elif action==7:self.acknowledge(next_action=8)
        elif action==8:self.acknowledge(next_action=9)
        elif action==9:self.acknowledge(256-self.read_position,self.target[self.read_position:],11 if self.replay else 10)
        elif action==10:self.acknowledge(next_action=11)
        elif action==11:self.acknowledge(next_action=12)
        elif action==12:self.acknowledge(next_action=0)
        else:raise AssertionError('no effect after terminal receipt')
    def to(self,action):
        for _ in range(16):
            if self.action==action:return
            require(self.action!=0,'requested effect not on declared success path');self.advance_one()
        raise AssertionError('independent fixed trace length exceeded')
    def finish(self):self.to(0)
    def quarantine(self,raw,label,reason):
        self.status=3;self.phase=15;self.action=0;self.reason=reason;self.call(raw,label)
    def rejected(self,raw,label):
        before=self.session.buffers();value,output,workspace=self.session.call(raw,label)
        require(value==ABI and (output,workspace)==before,'bad ABI/state must not change an admitted frame')
    def observe(self):self.call(self.source(90,action=0),'observe')

def raw_initial(O,expected,*,nonce=NONCE,txn=TXN):
    return O.request(event=0,serial=0,action=0,result=0,nonce=nonce,
        payload=expected+TARGET+txn+REQUEST)

def run(engine,O,group):
    require(group in GROUPS,'fixed head group required')
    def init_bad(name,source,output=None,workspace=None,unchanged=False):
        session=engine.session(name,output,workspace);before=session.buffers()
        value,after,work=session.call(source,'rejected-initialize')
        require(value==ABI,'invalid head initialization accepted: '+name)
        if unchanged:require((after,work)==before,'ABI preflight modified scratch: '+name)
    if group==GROUPS[0]:
        for generation in (0,1,7):
            f=Frame(engine,O,'generation-'+str(generation),head(O,generation));f.finish()
            require(f.status==0 and f.phase==13 and f.possible==f.sync==1,'full commit trace did not confirm')
    elif group==GROUPS[1]:
        f=Frame(engine,O,'all-positive-partials')
        for action in range(1,13):
            f.to(action)
            if action in (2,6,9):
                data=f.expected if action==2 else f.target
                for count in (1,63,192):
                    offset=f.read_position;f.claim();f.acknowledge(count,data[offset:offset+count],action if offset+count<256 else {2:3,6:7,9:10}[action])
            elif action==4:
                for count in (1,63,192):
                    offset=f.write_position;f.claim();f.acknowledge(count,next_action=4 if offset+count<256 else 5)
            else:f.advance_one()
        require(f.status==0,'partial IO trace did not confirm')
        for action in (1,2,4,5,6,8,9):
            f=Frame(engine,O,'eintr-retry-'+str(action));f.to(action);f.claim()
            offset=f.read_position;written=f.write_position
            f.acknowledge(U64-3,next_action=action)
            require((f.read_position,f.write_position)==(offset,written),'EINTR advanced offsets')
            f.finish()
    elif group==GROUPS[2]:
        expected=head(O);target=O.target_head(expected,TARGET,TXN,REQUEST)
        replay=Frame(engine,O,'exact-entire-target-replay',expected,target);replay.finish()
        require(replay.replay==1 and replay.possible==replay.sync==1,'replay durability receipt incomplete')
        conflict=head(O,2,root=sha256(b'other-writer-root').digest())
        f=Frame(engine,O,'other-writer-conflict',expected,conflict);f.finish()
        require(f.status==2 and f.phase==14 and f.possible==f.sync==0,'conflict silently published')
        foreign=head(O,1,uuid=bytes(range(16,0,-1)))
        f=Frame(engine,O,'foreign-store-read',expected);f.to(2);f.claim();f.acknowledge(256,foreign,reason=20)
    elif group==GROUPS[3]:
        for action in range(1,13):
            f=Frame(engine,O,'lost-ack-'+str(action));f.to(action);f.claim();raw=f.source(3)
            f.quarantine(raw,'lost',4);f.observe()
            require(f.possible==(1 if action>=7 else 0),'publication uncertainty boundary differs')
            f.rejected(f.source(1,action=action),'no-retry-after-unknown')
    elif group==GROUPS[4]:
        for action in (3,7,10,11,12):
            f=Frame(engine,O,'eintr-no-retry-'+str(action));f.to(action);f.claim();f.acknowledge(U64-3,reason=8);f.observe()
    elif group==GROUPS[5]:
        for action,value,reason in ((1,1,10),(3,1<<31,11),(4,0,12),(4,257,12),(5,1,13),(7,1,13),(8,1,13),(10,1,13),(11,1,13),(12,1,13)):
            f=Frame(engine,O,'effect-'+str(action)+'-'+str(value));f.to(action);f.claim();f.acknowledge(value,reason=reason)
        for action in (2,6,9):
            f=Frame(engine,O,'read-zero-'+str(action));f.to(action);f.claim();f.acknowledge(0,reason=16)
        f=Frame(engine,O,'actual-negative-errno');f.to(7);f.claim();f.acknowledge(U64-27,reason=8)
        f=Frame(engine,O,'payload-on-nonread');f.to(3);f.claim();f.acknowledge(19,b'x',reason=9)
    elif group==GROUPS[6]:
        f=Frame(engine,O,'wrong-nonce');f.rejected(f.source(1,nonce=bytes(range(49,65))),'foreign-nonce')
        f=Frame(engine,O,'wrong-serial');f.quarantine(f.source(1,serial=0),'serial',1)
        f=Frame(engine,O,'wrong-action');f.quarantine(f.source(1,action=2),'action',1)
        f=Frame(engine,O,'ack-without-claim');f.quarantine(f.source(2),'unclaimed',6)
        f=Frame(engine,O,'duplicate-claim');f.claim();f.quarantine(f.source(1),'second-claim',5)
        f=Frame(engine,O,'unknown-event');f.quarantine(f.source(4),'event',6)
        f=Frame(engine,O,'malformed-lost-response');f.quarantine(f.source(3,result=1),'lost-with-value',3)
        f=Frame(engine,O,'serial-exhaustion')
        _,w=f.session.buffers();f.serial=U64-1;f.session.replace_private_workspace_for_control(seal(word(w,24,f.serial)))
        f.quarantine(f.source(1),'serial-no-wrap',2)
    elif group==GROUPS[7]:
        good=head(O)
        for at in (0,7,8,16,32,40,80,112,128,160,168,223,224,255):
            bad=replace(good,at,bytes([good[at]^1]));init_bad('corrupt-'+str(at),raw_initial(O,bad))
        for at,value in ((8,2),(16,0),(40,1),(160,2),(168,1)):
            bad=word(good,at,value)
            if at==16:bad=replace(bad,16,bytes(16))
            init_bad('well-hashed-invalid-'+str(at),raw_initial(O,rehash(bad)))
        for action in (2,6,9):
            f=Frame(engine,O,'bad-read-hash-'+str(action));f.to(action);f.claim()
            data=f.expected if action==2 else f.target;bad=replace(data,255,bytes([data[255]^1]))
            f.acknowledge(256,bad,reason=17 if action==2 else 18)
    elif group==GROUPS[8]:
        init_bad('generation-exhaustion',raw_initial(O,head(O,U64)))
        f=Frame(engine,O,'last-generation',head(O,U64-1));f.finish()
        require(O.decode_head(f.target)['generation']==U64,'last generation did not stay exact')
        prior=head(O,3,txn=TXN);init_bad('transaction-reuse',raw_initial(O,prior))
        init_bad('zero-transaction',raw_initial(O,head(O),txn=bytes(16)))
    elif group==GROUPS[9]:
        base=raw_initial(O,head(O))
        for size in (0,127,128,463,465):
            b=base[:size] if size<len(base) else base+bytes(size-len(base))
            init_bad('source-'+str(size),b,unchanged=True)
        for size in (0,1151):init_bad('output-'+str(size),base,output=bytes(size),unchanged=True)
        for size in (0,2047,2049):init_bad('workspace-'+str(size),base,workspace=bytes(size),unchanged=True)
        for at in (0,40,95,112,127):init_bad('header-'+str(at),replace(base,at,b'\xff'),unchanged=True)
        for at in (16,24,32):init_bad('init-word-'+str(at),word(base,at,1),unchanged=True)
        init_bad('zero-nonce',replace(base,96,bytes(16)),unchanged=True)
    elif group==GROUPS[10]:
        base=raw_initial(O,head(O))
        for at in (0,247,248,1104,2047):init_bad('dirty-init-'+str(at),base,
            workspace=replace(bytes(2048),at,b'\x01'),unchanged=True)
        for at in (0,8,24,96,144,248,256,512,768,1104,2047):
            f=Frame(engine,O,'corrupt-private-state-'+str(at));_,w=f.session.buffers();bad=replace(w,at,bytes([w[at]^1]))
            f.session.replace_private_workspace_for_control(bad);f.rejected(f.source(90,action=0),'invalid-seal-or-state')
        f=Frame(engine,O,'well-sealed-invalid-reserved');_,w=f.session.buffers();f.session.replace_private_workspace_for_control(seal(replace(w,144,b'\x01')))
        f.rejected(f.source(90,action=0),'well-sealed-malformed-state')
    elif group==GROUPS[11]:
        f=Frame(engine,O,'confirmed-terminal-observe');f.finish();f.observe();f.observe()
        for event in (1,2,3):f.rejected(f.source(event,action=1),'terminal-event-'+str(event))
        f.rejected(f.source(90,serial=f.serial-1,action=0),'stale-observe')
        f=Frame(engine,O,'conflict-terminal-observe',current=head(O,2));f.finish();f.observe()
    require(engine.cases,'whole head group absent')
    return dict(group=group,cases=engine.cases,independent_head_hash_oracle=True,independently_specified_action_traces=True,
        syscall_results_are_test_inputs=True,actual_filesystem_IO=False,durability=False,default=False)

"""Independent format vectors; hashlib is a development oracle only."""
from hashlib import sha256
import struct

GROUPS=(
 'catalog-genesis-empty-pages','catalog-ten-single-transitions','catalog-joint-transaction',
 'catalog-all-table-transition','catalog-uuid-generation','catalog-header-selector',
 'catalog-extents','catalog-table-order','catalog-root-bindings','catalog-sha-corruption',
 'catalog-change-mask','catalog-dirty-scratch','catalog-count-boundaries')
ABI=0xfffffffd
INVALID=0xfffffffc
UPDATE=0xfffffffb
UUID=bytes(range(1,17))

def changed(raw,offset,value):
    b=bytearray(raw);b[offset:offset+len(value)]=value;return bytes(b)
def word(raw,offset,value):return changed(raw,offset,struct.pack('<Q',value))
def rehash(raw):return raw[:544]+sha256(raw[:544]).digest()

def cases(O,group):
    assert group in GROUPS
    genesis=O.genesis(UUID)
    pair=lambda i:(i,sha256(('nonempty-table-'+str(i)).encode()).digest())
    updates={i:pair(i) for i in range(1,11)}
    current=O.transition(genesis,UUID,0,updates)
    validate=lambda raw,generation=0,uuid=UUID: O.REQUEST_MAGIC+struct.pack('<QQQ',0,generation,0)+uuid+bytes(80)+raw
    transition=lambda changes:O.request(1,UUID,0,expected=genesis,updates=changes)
    rows=[]
    def add(name,source,value,payload=None,output_size=1152,workspace=None,unchanged=False):
        rows.append(dict(id=name,source=source,returned=value,payload=payload,
            output=bytes((i*17+0xa5)&255 for i in range(output_size)),
            workspace=bytes(2048) if workspace is None else workspace,unchanged=unchanged))
    if group==GROUPS[0]:
        add('genesis-ten-families',O.request(2,UUID),576,genesis)
        for i in range(1,11):
            p=O.empty_page(UUID,i);add('empty-'+str(i),O.request(3,UUID,table=i),96,p+sha256(p).digest())
    elif group==GROUPS[1]:
        for i in range(1,11):
            delta={i:pair(i)};add('table-'+str(i),transition(delta),576,O.transition(genesis,UUID,0,delta))
    elif group==GROUPS[2]:
        delta={i:pair(i) for i in (4,7,8,10)}
        add('request-slot-version-budget',transition(delta),576,O.transition(genesis,UUID,0,delta))
    elif group==GROUPS[3]:
        add('one-generation-ten-updates',transition(updates),576,current)
        add('validate-complete-new-root',O.request(0,UUID,1,expected=current),576,current)
    elif group==GROUPS[4]:
        add('different-store',validate(genesis,uuid=bytes(range(16,0,-1))),INVALID)
        add('wrong-generation',validate(genesis,1),INVALID)
        top=O.encode_catalog(UUID,(1<<64)-1,tuple(pair(i) for i in range(1,11)))
        add('max-generation-valid-read',validate(top,(1<<64)-1),576,top)
        source=word(transition({1:pair(1)}),16,(1<<64)-1)
        add('max-generation-no-wrap',source,UPDATE,unchanged=True)
        add('zero-uuid',changed(O.request(2,UUID),32,bytes(16)),ABI,unchanged=True)
    elif group==GROUPS[5]:
        base=O.request(2,UUID)
        for at in (0,56,63,64,111,120,127):add('header-'+str(at),changed(base,at,b'\xff'),ABI,unchanged=True)
        for at,value in ((8,4),(8,(1<<64)-1),(16,1),(24,1),(48,1)):
            add('header-word-'+str(at)+'-'+str(value),word(base,at,value),ABI,unchanged=True)
        for table in (0,11,(1<<64)-1):add('empty-selector-'+str(table),word(O.request(3,UUID,table=1),48,table),ABI,unchanged=True)
    elif group==GROUPS[6]:
        for op,source in ((2,O.request(2,UUID)),(0,O.request(0,UUID,expected=genesis)),(1,transition({1:pair(1)}))):
            for size in dict.fromkeys((0,127,len(source)-1,len(source)+1)):
                s=source[:size] if size<len(source) else source+bytes(size-len(source))
                add('source-'+str(op)+'-'+str(size),s,ABI,unchanged=True)
        for size in (0,1151):add('output-'+str(size),O.request(2,UUID),ABI,output_size=size,unchanged=True)
        for size in (0,2047,2049):add('workspace-'+str(size),O.request(2,UUID),ABI,workspace=bytes(size),unchanged=True)
    elif group==GROUPS[7]:
        for i in range(1,11):
            invalid=word(genesis,64+(i-1)*48,0 if i==1 else i-1)
            add('missing-or-duplicate-'+str(i),validate(rehash(invalid)),INVALID)
        invalid=bytearray(genesis);invalid[64:112],invalid[112:160]=genesis[112:160],genesis[64:112]
        add('reordered-first-two',validate(rehash(bytes(invalid))),INVALID)
        add('table-count-nine',validate(rehash(word(genesis,40,9))),INVALID)
    elif group==GROUPS[8]:
        for i in range(1,11):
            start=64+(i-1)*48+16
            add('zero-root-'+str(i),validate(rehash(changed(genesis,start,bytes(32)))),INVALID)
            wrong=sha256(O.empty_page(UUID,1 if i!=1 else 2)).digest()
            add('wrong-table-empty-root-'+str(i),validate(rehash(changed(genesis,start,wrong))),INVALID)
        wrong=sha256(O.empty_page(bytes(range(16,0,-1)),1)).digest()
        add('wrong-store-empty-root',validate(rehash(changed(genesis,80,wrong))),INVALID)
    elif group==GROUPS[9]:
        for at in (0,7,8,16,32,40,48,63,64,79,80,543,544,575):
            add('corrupt-'+str(at),validate(changed(genesis,at,bytes([genesis[at]^1]))),INVALID)
        for at in (0,8,48,63):add('well-hashed-malformed-'+str(at),validate(rehash(changed(genesis,at,bytes([genesis[at]^1])))),INVALID)
    elif group==GROUPS[10]:
        base=transition({1:pair(1)})
        for mask in (0,1024,(1<<64)-1):add('bad-mask-'+str(mask),word(base,24,mask),ABI,unchanged=True)
        add('zero-selected-digest',changed(base,712,bytes(32)),UPDATE)
        unchanged=word(base,704,0);unchanged=changed(unchanged,712,genesis[80:112])
        add('selected-unchanged-pair',unchanged,UPDATE)
        add('nonzero-unselected-update',word(base,744,1),UPDATE)
        add('wrong-empty-selected-pair',word(base,704,0),UPDATE)
    elif group==GROUPS[11]:
        for fill in (0x5a,0xa5,0xff):
            add('dirty-genesis-'+str(fill),O.request(2,UUID),576,genesis,workspace=bytes([fill])*2048)
            add('dirty-validate-'+str(fill),O.request(0,UUID,expected=genesis),576,genesis,workspace=bytes([fill])*2048)
            add('dirty-error-'+str(fill),validate(changed(genesis,575,bytes([genesis[-1]^1]))),INVALID,workspace=bytes([fill])*2048)
    elif group==GROUPS[12]:
        huge=(1<<64)-1;delta={1:(huge,sha256(b'count-max-root').digest())}
        add('max-u64-count',transition(delta),576,O.transition(genesis,UUID,0,delta))
        empty_pair=(0,sha256(O.empty_page(UUID,1)).digest())
        add('nonempty-to-exact-empty',O.request(1,UUID,1,expected=current,updates={1:empty_pair}),576,O.transition(current,UUID,1,{1:empty_pair}))
        upper=O.encode_catalog(UUID,huge-1,tuple(pair(i) for i in range(1,11)))
        new={2:(huge,sha256(b'last-generation-root').digest())}
        add('last-valid-generation',O.request(1,UUID,huge-1,expected=upper,updates=new),576,O.transition(upper,UUID,huge-1,new))
    assert rows and len({r['id'] for r in rows})==len(rows)
    return rows

def run(engine,O,group):
    from observations import require,dump,pin
    rows=cases(O,group)
    dump(engine.output/'EXPECTED-CASES.json',[dict(id=r['id'],source=pin(r['source']),returned=r['returned'],
        output=pin(r['output']),workspace=pin(r['workspace']),expected_prefix=None if r['payload'] is None else r['payload'].hex(),
        preflight_unchanged=r['unchanged']) for r in rows])
    for row in rows:
        session=engine.session(row['id'],row['output'],row['workspace'])
        value,output,workspace=session.call(row['source'],'entry')
        require(value==row['returned'],'independent catalog result differs: '+row['id'])
        if row['payload'] is not None:require(output[:value]==row['payload'],'independent complete catalog/page bytes differ: '+row['id'])
        if row['unchanged']:require(output==row['output'] and workspace==row['workspace'],'rejected preflight wrote scratch: '+row['id'])
    require(engine.cases==[r['id'] for r in rows],'whole original case order differs')
    return dict(group=group,cases=[r['id'] for r in rows],independent_sha_oracle=True,all_native_vm_frames=True,
        catalogue_graph_verified=False,transaction_row_semantics_verified=False,durability=False)

